import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api/axios';
import toast from 'react-hot-toast';
import styles from './BookingHistory.module.css';

export default function BookingHistory() {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    api.get('/bookings/my')
      .then(({ data }) => setBookings(data))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  const handleCancel = async (id) => {
    if (!window.confirm('Cancel this booking?')) return;
    try {
      await api.put(`/bookings/${id}/cancel`);
      setBookings((prev) => prev.map((b) => b._id === id ? { ...b, status: 'cancelled' } : b));
      toast.success('Booking cancelled');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to cancel');
    }
  };

  if (loading) return <p className={styles.loading}>Loading bookings...</p>;

  return (
    <div className={styles.container}>
      <h2>My Bookings</h2>
      {bookings.length === 0 ? (
        <div className={styles.empty}>
          <p>No bookings yet.</p>
          <button className={styles.btn} onClick={() => navigate('/')}>Browse Movies</button>
        </div>
      ) : (
        <div className={styles.list}>
          {bookings.map((b) => {
            const movie = b.showtime?.movie;
            const st = b.showtime;
            return (
              <div key={b._id} className={`${styles.card} ${b.status === 'cancelled' ? styles.cancelled : ''}`}>
                <img
                  src={movie?.posterUrl || 'https://via.placeholder.com/80x120?text=N/A'}
                  alt={movie?.title}
                  className={styles.poster}
                />
                <div className={styles.info}>
                  <h3>{movie?.title}</h3>
                  <p>{st?.theater} • {st?.screen}</p>
                  <p>{st?.date} at {st?.startTime}</p>
                  <p>Seats: {b.seats.map((s) => s.seatNumber).join(', ')}</p>
                  <p>Total: ₹{b.totalAmount}</p>
                  <span className={`${styles.badge} ${styles[b.status]}`}>{b.status}</span>
                </div>
                <div className={styles.actions}>
                  <button className={styles.viewBtn} onClick={() => navigate(`/booking/${b._id}/confirmation`)}>
                    View
                  </button>
                  {b.status === 'confirmed' && (
                    <button className={styles.cancelBtn} onClick={() => handleCancel(b._id)}>
                      Cancel
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
